<?php
declare(strict_types=1);require_once __DIR__.'/_helper.php';izin_require_access($pdo);
$page_title='Izin Siswa';$menu=trim((string)($_GET['menu']??''));$menuQuery=$menu!==''?'&menu='.rawurlencode($menu):'';$tpId=izin_active_tapel_id($pdo);$search=trim((string)($_GET['q']??''));$status=trim((string)($_GET['status']??''));$tanggal=(string)($_GET['tanggal']??date('Y-m-d'));if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$tanggal))$tanggal=date('Y-m-d');
$where=['1=1'];$params=[];if($tpId){$where[]='iz.tahun_pelajaran_id=?';$params[]=$tpId;}$where[]='iz.tanggal=?';$params[]=$tanggal;if(in_array($status,['DIAJUKAN','DISETUJUI','DITOLAK','SELESAI'],true)){$where[]='iz.status=?';$params[]=$status;}if($search!==''){$where[]='(s.nama LIKE ? OR s.nis LIKE ? OR s.nisn LIKE ? OR mk.nama LIKE ?)';$q="%$search%";array_push($params,$q,$q,$q,$q);}if(user_role()==='guru'&&!izin_is_wali($pdo))$where[]="iz.status IN ('DISETUJUI','SELESAI')";if(user_role()==='guru'&&izin_is_wali($pdo)){ $sc=izin_student_scope_sql($pdo,'s');$where[]=$sc['sql'];array_push($params,...$sc['params']);}$ws=implode(' AND ',$where);
$st=$pdo->prepare("SELECT iz.*,s.nis,s.nisn,s.nama AS siswa_nama,mk.nama AS kelas_nama,u.nama AS penyetuju_nama FROM izin_siswa iz INNER JOIN siswa s ON s.id=iz.siswa_id INNER JOIN master_kelas mk ON mk.id=iz.kelas_id LEFT JOIN users u ON u.id=iz.disetujui_oleh WHERE $ws ORDER BY CASE iz.status WHEN 'DIAJUKAN' THEN 1 WHEN 'DISETUJUI' THEN 2 WHEN 'SELESAI' THEN 3 ELSE 4 END,iz.jam_pengajuan DESC,iz.id DESC");$st->execute($params);$rows=$st->fetchAll();$counts=['DIAJUKAN'=>0,'DISETUJUI'=>0,'DITOLAK'=>0,'SELESAI'=>0];foreach($rows as $r){$counts[$r['status']]??=0;$counts[$r['status']]++;}
require_once __DIR__.'/../layouts/header.php';require_once __DIR__.'/../layouts/sidebar.php';
?><main class="main"><header class="topbar"><div class="topbar-title">Izin Siswa</div><div class="topbar-user"><?=e(user_name())?></div></header><section class="content izin-module"><div class="page-header"><div><h1>Izin Siswa</h1><p>Pulang lebih awal atau keluar sementara. Absensi pagi tetap tersimpan.</p></div><?php if(izin_is_wali($pdo)):?><a class="btn btn-primary" href="<?=BASE_URL?>izin/tambah.php<?=e($menu!==''?'?menu='.rawurlencode($menu):'')?>"><i class="bi bi-plus-lg"></i> Ajukan Izin</a><?php endif;?></div>
<div class="stats-grid izin-stats-grid" style="margin-bottom:18px"><?php foreach([['DIAJUKAN','Diajukan','hourglass-split'],['DISETUJUI','Disetujui','check-circle-fill'],['DITOLAK','Ditolak','x-circle-fill'],['SELESAI','Selesai','box-arrow-right']] as $x):?><div class="stat-card"><div class="stat-icon"><i class="bi bi-<?=$x[2]?>"></i></div><div><div class="stat-label"><?=$x[1]?></div><div class="stat-value"><?=$counts[$x[0]]?></div></div></div><?php endforeach;?></div>
<div class="form-card" style="margin-bottom:18px"><form method="get" class="form-grid" style="align-items:end"><label>Tanggal<input class="form-control" type="date" name="tanggal" value="<?=e($tanggal)?>"></label><label>Status<select class="form-control" name="status"><option value="">Semua Status</option><?php foreach(['DIAJUKAN'=>'Diajukan','DISETUJUI'=>'Disetujui','DITOLAK'=>'Ditolak','SELESAI'=>'Selesai'] as $k=>$v):?><option value="<?=$k?>" <?=$status===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select></label><label style="grid-column:span 2">Cari<input class="form-control" name="q" value="<?=e($search)?>" placeholder="Nama / NIS / NISN / Kelas"></label><div><button class="btn btn-primary"><i class="bi bi-search"></i> Terapkan</button> <a class="btn btn-secondary" href="<?=BASE_URL?>izin/index.php<?=e($menu!==''?'?menu='.rawurlencode($menu):'')?>">Reset</a></div></form></div>
<div class="table-card"><div class="table-responsive"><table class="table"><thead><tr><th>No</th><th>Siswa</th><th>Kelas</th><th>Jenis</th><th>Alasan</th><th>Jam</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="8" class="text-center">Belum ada data izin.</td></tr><?php endif;?><?php foreach($rows as $i=>$r):?><tr><td><?=$i+1?></td><td><strong><?=e($r['siswa_nama'])?></strong><br><small><?=e($r['nis'])?></small></td><td><?=e($r['kelas_nama'])?></td><td><?=e($r['jenis']==='PULANG_LEBIH_AWAL'?'Pulang Lebih Awal':'Keluar Sementara')?></td><td><?=e($r['alasan'])?><?php if($r['keterangan']):?><br><small><?=e($r['keterangan'])?></small><?php endif;?></td><td><?=e(substr((string)$r['jam_pengajuan'],0,5))?><?php if($r['jam_keluar']):?><br><small>Keluar <?=e(substr((string)$r['jam_keluar'],0,5))?></small><?php endif;?></td><td><span class="badge badge-<?=e(izin_status_class($r['status']))?>"><?=e(izin_status_label($r['status']))?></span></td><td><a class="btn btn-sm btn-secondary btn-icon-sm" title="Detail izin" aria-label="Detail izin" href="<?=BASE_URL?>izin/detail.php?id=<?=$r['id']?><?=e($menuQuery)?>"><i class="bi bi-eye" aria-hidden="true"></i></a></td></tr><?php endforeach;?></tbody></table></div></div></section></main><?php require_once __DIR__.'/../layouts/footer.php';?>
